"""Regression tests for source selection and compatibility diagnostic auditing."""
import io
from pathlib import Path
import tempfile
import unittest

import check_gopls as gate


class GateTests(unittest.TestCase):
    def test_selects_only_nongenerated_go_sources(self):
        sources = {
            'plain.go': 'package example\n',
            'openapi.go': '/*\nAPI spec\n\n\n\n\n\n*/\n// Code generated by OpenAPI Generator; DO NOT EDIT.\npackage example\n',
            'lens.go': 'package example\n// Code generated by go generate; DO NOT EDIT.\n',
            'raw.go': 'package example\nconst marker = `// Code generated by fake; DO NOT EDIT.`\n',
            'quoted.go': 'package example\nconst marker = "// Code generated by fake; DO NOT EDIT."\n',
            'fragment.go': 'package example\n// Code generated fragment\n',
            'inline.go': 'package example // Code generated by fake; DO NOT EDIT.\n',
            'block.go': 'package example\n/* Code generated by fake; DO NOT EDIT. */\n',
            'escaped.go': 'package example\nconst marker = "\\\"// Code generated by fake; DO NOT EDIT."\n',
        }
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            for name, source in sources.items():
                (root / name).write_text(source)
            selected = gate.select_files(root, sources)
        self.assertEqual(['plain.go', 'raw.go', 'quoted.go', 'fragment.go', 'inline.go', 'block.go', 'escaped.go'], selected)

    def test_audits_only_bounded_exact_legacy_diagnostics(self):
        approved = ('internal/server/feature_annotation_deprecated.go:30:11-17: req.Id'
                    ' is deprecated: Marked as deprecated in dictybase/feature_annotation/feature_annotation.proto.\n')
        report = io.StringIO()
        gate.audit_diagnostics(approved, Path.cwd(), report)
        self.assertIn('audited compatibility diagnostics: 1', report.getvalue())
        cases = {
            'too many': approved * 13,
            'other symbol': approved.replace('req.Id', 'req.Other'),
            'other file': approved.replace('feature_annotation_deprecated.go', 'other.go'),
            'changed reason': approved.replace('Marked as deprecated', 'New deprecated contract'),
            'extra diagnostic': approved + 'internal/server/feature_annotation_deprecated.go:31:1: interface{} can be replaced by any\n',
            'unknown output': 'cannot load package\n',
        }
        for name, output in cases.items():
            with self.subTest(name=name), self.assertRaises(gate.DiagnosticsError):
                gate.audit_diagnostics(output, Path.cwd(), io.StringIO())


if __name__ == '__main__':
    unittest.main()
